const fullpath = path.join(settings.folder, filename);
if (Object.hasOwn(request.body, 'vc_changes')) {
        const vcCommit = globalThis[Symbol.for('virtual-companion.bridge')]?.commitDocument;
        if (!vcCommit) return response.status(503).json({ code: 'VC_DOCUMENT_UNAVAILABLE', message: 'Configuration unavailable' });
    return vcCommit(request, response, fullpath, { result: { name }, allowCreate: true,
        write(next) { writeFileAtomicSync(fullpath, JSON.stringify(next, null, 4), 'utf-8'); } });
}
writeFileAtomicSync(fullpath, JSON.stringify(request.body.preset, null, 4), 'utf-8');
